import{_ as i}from"./chunks/agenten-delegationskreislauf.Dy9vhm9B.js";import{_ as t,C as r,o as s,c as a,ai as h,E as d}from"./chunks/framework.kPxgjqLK.js";const w=JSON.parse('{"title":"Was ein KI-Agent ist","description":"","frontmatter":{"title":"Was ein KI-Agent ist"},"headers":[],"relativePath":"kapitel/01-was-ein-ki-agent-ist.md","filePath":"kapitel/01-was-ein-ki-agent-ist.md"}'),l={name:"kapitel/01-was-ein-ki-agent-ist.md"};function u(o,e,g,c,m,f){const n=r("FeedbackForm");return s(),a("div",null,[e[0]||(e[0]=h('<p><img src="'+i+'" alt="Agenten-Delegationskreislauf"></p><h2 id="kapitel-1-was-ein-ki-agent-ist" tabindex="-1">Kapitel 1: Was ein KI-Agent ist <a class="header-anchor" href="#kapitel-1-was-ein-ki-agent-ist" aria-label="Permalink to &quot;Kapitel 1: Was ein KI-Agent ist&quot;">​</a></h2><h2 id="vom-chat-zur-delegation" tabindex="-1">Vom Chat zur Delegation <a class="header-anchor" href="#vom-chat-zur-delegation" aria-label="Permalink to &quot;Vom Chat zur Delegation&quot;">​</a></h2><p>Sie haben eine Frage. Sie öffnen ein Chatfenster, tippst sie ein, bekommst eine Antwort. Das ist ein Chatbot. Hilfreich, schnell, aber grundsätzlich reaktiv. Er antwortet auf das, was Sie schreiben. Er merkt sich nichts über die Sitzung hinaus. Er hat keinen Zugriff auf Ihre Dateien, Ihren Kalender, Ihre Projekte. Und er führt keine Schritte durch, die Sie nicht explizit angestoßen hast.</p><p>Ein KI-Agent ist etwas anderes.</p><h2 id="der-unterschied-zwischen-chatbot-workflow-und-agent" tabindex="-1">Der Unterschied zwischen Chatbot, Workflow und Agent <a class="header-anchor" href="#der-unterschied-zwischen-chatbot-workflow-und-agent" aria-label="Permalink to &quot;Der Unterschied zwischen Chatbot, Workflow und Agent&quot;">​</a></h2><p>Um zu verstehen, was ein Agent ist, hilft es, ihn gegen zwei verwandte Konzepte abzugrenzen: den Chatbot auf der einen Seite und den festen Workflow auf der anderen.</p><p>Ein Chatbot beantwortet Fragen im Dialog. Seine Stärke liegt in Texterzeugung, Zusammenfassungen, Brainstorming und Erklärungen. Seine Grenze liegt darin, dass er keine Handlungen ausführt. Er denkt, aber er tut nicht.</p><p>Ein Workflow ist ein festgelegter Ablauf. Wenn Bedingung A erfüllt ist, folgt Schritt B, dann Schritt C. Workflows sind zuverlässig, weil sie immer gleich ablaufen. Sie sind schwach bei allem, was Abweichungen erfordert, weil jede neue Situation eine Anpassung des festgelegten Pfades verlangt. Ein klassisches Beispiel: Wenn eine neue Rechnung im Posteingang landet, extrahiere die Daten und trage sie in die Tabelle ein. Das funktioniert, solange Rechnungen immer gleich aussehen.</p><p>Ein Agent verbindet beides und geht darüber hinaus. Er bekommt ein Ziel, nicht einen festen Ablauf. Er entscheidet eigenständig, welche Schritte notwendig sind, welche Werkzeuge er nutzt, in welcher Reihenfolge er vorgeht und wann er ein Zwischenergebnis zur Prüfung vorlegt. Er kann mit unerwarteten Situationen umgehen, weil er nicht einem Script folgt, sondern das Ziel im Blick behält und seinen Weg dorthin dynamisch anpasst.</p><p>Diese Unterscheidung ist zentral für die gesamte Buchlogik. Viele Selbständige brauchen zu Beginn keinen Agenten, sondern einen besseren Workflow oder einen gut formulierten Prompt. Die Kunst liegt darin zu erkennen, wann welche Lösung passt.</p><h2 id="wann-ein-einfacher-prompt-reicht" tabindex="-1">Wann ein einfacher Prompt reicht <a class="header-anchor" href="#wann-ein-einfacher-prompt-reicht" aria-label="Permalink to &quot;Wann ein einfacher Prompt reicht&quot;">​</a></h2><p>Ein guter Prompt ist die einfachste Lösung und meistens die richtige, solange die Aufgabe klar umrissen ist, einmalig oder selten vorkommt, keine externen Werkzeuge braucht und das Ergebnis direkt im Chatfenster entstehen kann.</p><p>Beispiele dafür sind das Umformulieren eines Absatzes, das Zusammenfassen einer Notiz, das Brainstormen von Ideen für einen Blogartikel oder das Erstellen einer einfachen Gliederung. Hier ist ein Prompt das richtige Mittel, weil er schnell, transparent und ausreichend ist.</p><p>Die Schwäche des Prompts zeigt sich, wenn die Aufgabe mehrere Schritte erfordert, wenn Daten aus verschiedenen Quellen zusammengeführt werden müssen oder wenn die Aufgabe regelmäßig wiederkehrt und jedes Mal neu angestoßen werden müsste. Dann lohnt sich der Blick auf strukturiertere Lösungen.</p><h2 id="wann-ein-workflow-die-bessere-wahl-ist" tabindex="-1">Wann ein Workflow die bessere Wahl ist <a class="header-anchor" href="#wann-ein-workflow-die-bessere-wahl-ist" aria-label="Permalink to &quot;Wann ein Workflow die bessere Wahl ist&quot;">​</a></h2><p>Ein fester Workflow lohnt sich, wenn eine Aufgabe oft vorkommt, immer die gleiche Struktur hat und das Ergebnis klar definiert ist. Klassische Beispiele für Selbständige sind das Umbenennen von Dateien nach einem einheitlichen Schema, das Zusammenführen von Tabellendaten aus verschiedenen Monaten, das Versenden einer wöchentlichen Statusübersicht an feste Empfänger oder das Erstellen eines Angebotsentwurfs auf Basis einer Vorlage.</p><p>Workflows sind zuverlässig. Sie sind vorhersehbar. Und sie sind leicht zu prüfen, weil das Ergebnis immer gleich aussehen soll. Für wiederkehrende, strukturierte Aufgaben ist ein gut aufgebauter Workflow einem Agenten häufig vorzuziehen, weil er einfacher, günstiger und leichter zu kontrollieren ist.</p><h2 id="wann-ein-agent-echten-mehrwert-bringt" tabindex="-1">Wann ein Agent echten Mehrwert bringt <a class="header-anchor" href="#wann-ein-agent-echten-mehrwert-bringt" aria-label="Permalink to &quot;Wann ein Agent echten Mehrwert bringt&quot;">​</a></h2><p>Ein Agent ist dann die richtige Wahl, wenn eine Aufgabe komplex ist und viele Zwischenschritte erfordert, wenn die Schritte von Ergebnissen abhängen, die erst während der Arbeit entstehen, wenn verschiedene Werkzeuge kombiniert werden müssen und wenn Sie nicht jeden Schritt selbst definieren kannst oder willst.</p><p>Stellen Sie sich folgende Aufgabe vor: Sie wollen wissen, wie Ihre drei größten Wettbewerber ihr Angebot aktuell positionieren, was sie in den letzten Wochen kommuniziert haben und welche Themen noch unbesetzt sind. Um das herauszufinden, müsste jemand mehrere Websites prüfen, Texte vergleichen, Muster erkennen und die Erkenntnisse in einem klaren Briefing zusammenfassen. Das ist keine Frage, die ein einzelner Prompt beantwortet. Es ist eine Aufgabe, die mehrere Schritte erfordert, Werkzeuge wie eine Websuche, und das Urteilsvermögen, um Relevantes von Irrelevantem zu trennen.</p><p>Ein Agent kann diese Aufgabe übernehmen, eigenständig durch die notwendigen Schritte arbeiten, Zwischenergebnisse intern weiterverarbeiten und Ihnen am Ende ein Ergebnis vorlegen, das Sie prüfen, korrigierst und verwendest.</p><p>Wichtig dabei: Der Agent schließt die Aufgabe nicht ab. Sie tun es. Die menschliche Freigabe ist kein optionaler Schritt, sondern ein grundlegendes Prinzip. Besonders bei allem, was externe Kommunikation, finanzielle Konsequenzen oder rechtliche Bedeutung hat.</p><h2 id="was-einen-agenten-technisch-ausmacht" tabindex="-1">Was einen Agenten technisch ausmacht <a class="header-anchor" href="#was-einen-agenten-technisch-ausmacht" aria-label="Permalink to &quot;Was einen Agenten technisch ausmacht&quot;">​</a></h2><p>Hinter jedem Agent steckt ein Sprachmodell, das Texte versteht und erzeugt. Was einen Agenten vom einfachen Chatbot unterscheidet, ist die Verbindung dieses Modells mit Werkzeugen, mit Gedächtnis und mit der Fähigkeit zur Planung.</p><p>Werkzeuge sind externe Fähigkeiten, die ein Agent nutzen kann: eine Websuche, das Lesen einer Datei, das Schreiben in ein Dokument, das Ausführen eines Programms, die Verbindung zu einem Kalender oder einer Datenbank. Ein Agent ohne Werkzeuge ist wie ein kompetenter Mitarbeiter ohne Schreibtisch und ohne Computer. Er kann denken, aber nicht handeln.</p><p>Gedächtnis ist die Fähigkeit, Informationen über einzelne Sitzungen hinaus zu behalten. Manche Agenten haben ein kurzfristiges Gedächtnis nur für die aktuelle Sitzung. Andere speichern Informationen dauerhaft und können bei der nächsten Aufgabe auf frühere Erfahrungen zurückgreifen. Für Selbständige ist langfristiges Gedächtnis besonders wertvoll, weil es bedeutet, dass ein Agent Ihren Stil kennt, Ihre Kundenprojekte kennt und Ihre Arbeitsweise versteht.</p><p>Planung ist die Fähigkeit, ein Ziel in Teilschritte zu zerlegen und diese Schritte in einer sinnvollen Reihenfolge auszuführen. Ein planender Agent fragt nicht nach jedem Schritt, was als nächstes zu tun ist. Er entwickelt eine eigene Strategie und passt sie an, wenn Ergebnisse neue Informationen liefern.</p><h2 id="das-prinzip-der-minimalen-komplexitat" tabindex="-1">Das Prinzip der minimalen Komplexität <a class="header-anchor" href="#das-prinzip-der-minimalen-komplexitat" aria-label="Permalink to &quot;Das Prinzip der minimalen Komplexität&quot;">​</a></h2><p>Eine der wichtigsten Empfehlungen für den Einstieg in die Agentenarbeit lautet: Beginne immer mit der einfachsten Lösung. Ein guter Prompt ist besser als ein schlecht konfigurierter Workflow. Ein verlässlicher Workflow ist besser als ein schlecht definierter Agent. Mehr Autonomie bedeutet nicht automatisch bessere Ergebnisse. Sie bedeutet mehr Spielraum für Fehler, wenn Ziele, Grenzen und Prüfmechanismen nicht klar sind.</p><p>Agenten sollten nicht eingesetzt werden, weil sie modern klingen. Sie sollten eingesetzt werden, weil eine konkrete Aufgabe von ihren Eigenschaften profitiert: von der Fähigkeit, eigenständig zu planen, Werkzeuge zu kombinieren und in einem iterativen Prozess bessere Ergebnisse zu liefern, als ein einfacher Schritt es könnte.</p><p>Dieses Prinzip zieht sich durch das gesamte Buch. Jedes Kapitel fragt zuerst: Was ist die einfachste Lösung, die zuverlässig funktioniert? Und dann: Wann lohnt es sich, einen Schritt weiterzugehen?</p><h2 id="die-vier-grundeigenschaften-eines-guten-agenten-setups" tabindex="-1">Die vier Grundeigenschaften eines guten Agenten-Setups <a class="header-anchor" href="#die-vier-grundeigenschaften-eines-guten-agenten-setups" aria-label="Permalink to &quot;Die vier Grundeigenschaften eines guten Agenten-Setups&quot;">​</a></h2><p>Wer mit Agenten arbeitet, sollte von Anfang an vier Eigenschaften im Blick behalten, die über Erfolg oder Misserfolg entscheiden.</p><p>Erstens: Ein klares Ziel. Agenten sind keine allwissenden Assistenten. Sie brauchen eine präzise Aufgabe, ein definiertes Ausgabeformat und klare Grenzen dessen, was sie tun dürfen und was nicht.</p><p>Zweitens: Ein Budget. Zeit, Tokens und API-Kosten sind begrenzte Ressourcen. Jede Agentenroutine sollte ein definiertes Maximum haben, bei dessen Erreichen sie anhält und Rückfrage stellt, anstatt weiter zu laufen.</p><p>Drittens: Stopregeln. Ein Agent sollte wissen, wann er aufhören soll. Nicht nur wenn er fertig ist, sondern auch wenn er feststeckt, wenn er unsichere Entscheidungen treffen müsste oder wenn das Ergebnis von einer menschlichen Einschätzung abhängt.</p><p>Viertens: Menschliche Freigabe an den richtigen Stellen. Nicht für jeden Schritt. Aber für alle Schritte, die irreversibel sind, externe Konsequenzen haben oder Unsicherheiten enthalten, die ein Mensch besser beurteilt als ein Modell.</p><p>Diese vier Eigenschaften sind kein bürokratisches Gerüst. Sie sind die Grundlage dafür, dass Agenten tatsächlich verlässlich funktionieren, anstatt gelegentlich gut und gelegentlich problematisch.</p><h2 id="agenten-als-mitarbeiter-denken" tabindex="-1">Agenten als Mitarbeiter denken <a class="header-anchor" href="#agenten-als-mitarbeiter-denken" aria-label="Permalink to &quot;Agenten als Mitarbeiter denken&quot;">​</a></h2><p>Eine Metapher, die sich durch das gesamte Buch zieht: Denken Sie an einen Agenten wie an einen neuen Mitarbeiter. Nicht wie an einen Computer, der Befehle ausführt. Sondern wie an eine Person, die Sie briefst, die Fragen stellt, wenn etwas unklar ist, die Ergebnisse liefert, die Sie prüfen, und die mit der Zeit besser wird, weil sie mehr über Ihre Arbeitsweise und Ihre Projekte weiß.</p><p>Einem neuen Mitarbeiter gibt man am Anfang keine kritischen Aufgaben mit großer Wirkung. Man gibt ihm überschaubare Aufgaben, schaut sich die Ergebnisse an, gibt Feedback und erweitert seinen Verantwortungsbereich schrittweise, wenn das Vertrauen gewachsen ist.</p><p>Genauso sollte man mit Agenten umgehen. Das erste Projekt ist nicht die automatische Kundenkommunikation. Das erste Projekt ist ein Recherchebriefing, das Sie danach kontrollierst. Dann ein Entwurf, den Sie überarbeiten. Dann eine Routineaufgabe, die Sie eine Woche lang täglich prüfst. Und dann, wenn Sie wissen, wie der Agent arbeitet und wo seine Grenzen liegen, können Sie ihm mehr Verantwortung geben.</p><h2 id="drei-aufgaben-zum-einstieg" tabindex="-1">Drei Aufgaben zum Einstieg <a class="header-anchor" href="#drei-aufgaben-zum-einstieg" aria-label="Permalink to &quot;Drei Aufgaben zum Einstieg&quot;">​</a></h2><p>Bevor Sie in die nächsten Kapitel einsteigst, lohnt es sich, kurz innezuhalten und drei Fragen zu beantworten. Welche wiederkehrende Aufgabe kostet Sie jede Woche am meisten Zeit, obwohl sie klar strukturiert ist? Welche Recherche oder Zusammenfassung wünschen Sie sich, die Sie bisher nicht regelmäßig machst, weil sie zu zeitaufwändig ist? Welche Routine in Ihrer Arbeit wäre sofort besser, wenn jemand anderes die Vorarbeit erledigt?</p><p>Die Antworten auf diese drei Fragen sind Ihre persönliche Landkarte für dieses Buch. Sie zeigen Ihnen, wo Sie anfangen solltest, was sich lohnt und worauf Sie Sie im nächsten Kapitel am stärksten konzentrieren kannst.</p><p>Im nächsten Kapitel lernst Sie die vier konkreten Werkzeuge kennen, die in diesem Buch im Mittelpunkt stehen: Clawbot, Hermes, Claude Code und Codex. Sie wirst verstehen, was jedes dieser Werkzeuge kann, wofür es besonders geeignet ist, was seine Schwächen sind und wie Sie entscheiden, welches für Ihre Aufgaben passt.</p>',47)),d(n)])}const p=t(l,[["render",u]]);export{w as __pageData,p as default};
